//! Turns one input line into a typed [`Command`], applying the shape and
//! parameter-value checks of SPEC section 2 (steps 1 to 3).

use crate::error::{Error, ErrorCode::*, Result};
use serde_json::{Map, Value};
use std::ops::RangeInclusive;

/// Attributes named in a request; each is `None` when absent or `null`.
#[derive(Debug, Default)]
pub struct AttrPatch {
    pub visibility_timeout: Option<u32>,
    pub delay_seconds: Option<u32>,
    pub retention_seconds: Option<u32>,
    pub fifo: Option<bool>,
    pub content_based_deduplication: Option<bool>,
    pub dead_letter_queue: Option<String>,
    pub max_receive_count: Option<u32>,
}

#[derive(Debug)]
pub struct Send {
    pub queue: String,
    pub body: String,
    pub delay_seconds: Option<u32>,
    pub group_id: Option<String>,
    pub deduplication_id: Option<String>,
}

#[derive(Debug)]
pub enum Command {
    CreateQueue { name: String, attributes: AttrPatch },
    SetQueueAttributes { queue: String, attributes: AttrPatch },
    GetQueueAttributes { queue: String },
    ListQueues { prefix: Option<String> },
    DeleteQueue { queue: String },
    PurgeQueue { queue: String },
    Tick { seconds: u32 },
    SendMessage(Send),
    ReceiveMessage { queue: String, max_messages: u32, visibility_timeout: Option<u32> },
    DeleteMessage { queue: String, receipt_handle: String },
    ChangeMessageVisibility { queue: String, receipt_handle: String, visibility_timeout: u32 },
}

/// Whether `name` follows the queue name syntax of SPEC section 4.
pub fn is_valid_queue_name(name: &str) -> bool {
    let is_word = |s: &str| s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-');
    match name.strip_suffix(".fifo") {
        Some(stem) => (1..=75).contains(&stem.len()) && is_word(stem),
        None => (1..=80).contains(&name.len()) && is_word(name),
    }
}

fn invalid(message: String) -> Error {
    Error::new(InvalidParameterValue, message)
}

/// Read access to the members of a JSON object, where `null` counts as absent.
struct Params<'a>(&'a Map<String, Value>);

impl Params<'_> {
    fn get(&self, key: &str) -> Option<&Value> {
        self.0.get(key).filter(|v| !v.is_null())
    }

    /// Fails with `MissingParameter` for the first of `keys` that is absent.
    fn require(&self, keys: &[&str]) -> Result<()> {
        match keys.iter().find(|k| self.get(k).is_none()) {
            Some(key) => Err(Error::new(MissingParameter, format!("{key} is required"))),
            None => Ok(()),
        }
    }

    fn string(&self, key: &str) -> Result<Option<String>> {
        match self.get(key) {
            None => Ok(None),
            Some(Value::String(s)) => Ok(Some(s.clone())),
            Some(_) => Err(invalid(format!("{key} must be a string"))),
        }
    }

    /// A string whose presence `require` has already established.
    fn required_string(&self, key: &str) -> Result<String> {
        self.string(key)?.ok_or_else(|| Error::new(MissingParameter, format!("{key} is required")))
    }

    fn boolean(&self, key: &str) -> Result<Option<bool>> {
        match self.get(key) {
            None => Ok(None),
            Some(Value::Bool(b)) => Ok(Some(*b)),
            Some(_) => Err(invalid(format!("{key} must be a boolean"))),
        }
    }

    /// An integer written without fraction or exponent, within `range`.
    fn integer(&self, key: &str, range: RangeInclusive<u32>) -> Result<Option<u32>> {
        let Some(value) = self.get(key) else { return Ok(None) };
        let n = value.as_i64().and_then(|n| u32::try_from(n).ok()).filter(|n| range.contains(n));
        n.map(Some).ok_or_else(|| {
            invalid(format!("{key} must be an integer from {} to {}", range.start(), range.end()))
        })
    }

    fn required_integer(&self, key: &str, range: RangeInclusive<u32>) -> Result<u32> {
        self.integer(key, range)?.ok_or_else(|| Error::new(MissingParameter, format!("{key} is required")))
    }

    /// A string of 1 to 128 characters from `A-Z a-z 0-9 _ -`.
    fn identifier(&self, key: &str) -> Result<Option<String>> {
        let Some(s) = self.string(key)? else { return Ok(None) };
        let ok = (1..=128).contains(&s.len())
            && s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-');
        if ok { Ok(Some(s)) } else { Err(invalid(format!("{key} must be 1 to 128 characters from A-Z a-z 0-9 _ -"))) }
    }

    fn attributes(&self) -> Result<Option<AttrPatch>> {
        let Some(value) = self.get("Attributes") else { return Ok(None) };
        let Value::Object(map) = value else { return Err(invalid("Attributes must be an object".into())) };
        const NAMES: [&str; 7] = [
            "VisibilityTimeout",
            "DelaySeconds",
            "RetentionSeconds",
            "Fifo",
            "ContentBasedDeduplication",
            "DeadLetterQueue",
            "MaxReceiveCount",
        ];
        if let Some(unknown) = map.keys().find(|k| !NAMES.contains(&k.as_str())) {
            return Err(invalid(format!("unknown attribute {unknown}")));
        }
        let p = Params(map);
        Ok(Some(AttrPatch {
            visibility_timeout: p.integer("VisibilityTimeout", 0..=43200)?,
            delay_seconds: p.integer("DelaySeconds", 0..=900)?,
            retention_seconds: p.integer("RetentionSeconds", 60..=1_209_600)?,
            fifo: p.boolean("Fifo")?,
            content_based_deduplication: p.boolean("ContentBasedDeduplication")?,
            dead_letter_queue: p.string("DeadLetterQueue")?,
            max_receive_count: p.integer("MaxReceiveCount", 1..=1000)?,
        }))
    }
}

/// Parses one input line.
pub fn parse(line: &[u8]) -> Result<Command> {
    let bad = |what: &str| Error::new(InvalidRequest, what.to_owned());
    let text = std::str::from_utf8(line).map_err(|_| bad("line is not valid UTF-8"))?;
    let Ok(Value::Object(map)) = serde_json::from_str(text) else {
        return Err(bad("line is not a JSON object"));
    };
    let Some(Value::String(name)) = map.get("Command") else {
        return Err(bad("Command must be a string"));
    };
    let p = Params(&map);
    Ok(match name.as_str() {
        "CreateQueue" => {
            p.require(&["QueueName"])?;
            let name = p.required_string("QueueName")?;
            if !is_valid_queue_name(&name) {
                return Err(Error::new(QueueNameInvalid, format!("invalid queue name {name:?}")));
            }
            Command::CreateQueue { name, attributes: p.attributes()?.unwrap_or_default() }
        }
        "SetQueueAttributes" => {
            p.require(&["QueueName", "Attributes"])?;
            let queue = p.required_string("QueueName")?;
            let attributes = p.attributes()?.unwrap_or_default();
            Command::SetQueueAttributes { queue, attributes }
        }
        "GetQueueAttributes" => {
            p.require(&["QueueName"])?;
            Command::GetQueueAttributes { queue: p.required_string("QueueName")? }
        }
        "ListQueues" => Command::ListQueues { prefix: p.string("Prefix")? },
        "DeleteQueue" => {
            p.require(&["QueueName"])?;
            Command::DeleteQueue { queue: p.required_string("QueueName")? }
        }
        "PurgeQueue" => {
            p.require(&["QueueName"])?;
            Command::PurgeQueue { queue: p.required_string("QueueName")? }
        }
        "Tick" => {
            p.require(&["Seconds"])?;
            Command::Tick { seconds: p.required_integer("Seconds", 0..=1_209_600)? }
        }
        "SendMessage" => {
            p.require(&["QueueName", "Body"])?;
            let queue = p.required_string("QueueName")?;
            let body = p.required_string("Body")?;
            if !(1..=1024).contains(&body.len()) {
                return Err(invalid("Body must be 1 to 1024 bytes".into()));
            }
            Command::SendMessage(Send {
                queue,
                body,
                delay_seconds: p.integer("DelaySeconds", 0..=900)?,
                group_id: p.identifier("GroupId")?,
                deduplication_id: p.identifier("DeduplicationId")?,
            })
        }
        "ReceiveMessage" => {
            p.require(&["QueueName"])?;
            Command::ReceiveMessage {
                queue: p.required_string("QueueName")?,
                max_messages: p.integer("MaxMessages", 1..=10)?.unwrap_or(1),
                visibility_timeout: p.integer("VisibilityTimeout", 0..=43200)?,
            }
        }
        "DeleteMessage" => {
            p.require(&["QueueName", "ReceiptHandle"])?;
            Command::DeleteMessage {
                queue: p.required_string("QueueName")?,
                receipt_handle: p.required_string("ReceiptHandle")?,
            }
        }
        "ChangeMessageVisibility" => {
            p.require(&["QueueName", "ReceiptHandle", "VisibilityTimeout"])?;
            Command::ChangeMessageVisibility {
                queue: p.required_string("QueueName")?,
                receipt_handle: p.required_string("ReceiptHandle")?,
                visibility_timeout: p.required_integer("VisibilityTimeout", 0..=43200)?,
            }
        }
        other => return Err(bad(&format!("unknown command {other:?}"))),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn queue_name_syntax() {
        assert!(is_valid_queue_name("a"));
        assert!(is_valid_queue_name(&"a".repeat(80)));
        assert!(!is_valid_queue_name(&"a".repeat(81)));
        assert!(!is_valid_queue_name(""));
        assert!(is_valid_queue_name(&format!("{}.fifo", "a".repeat(75))));
        assert!(!is_valid_queue_name(&format!("{}.fifo", "a".repeat(76))));
        assert!(!is_valid_queue_name(".fifo"));
        assert!(!is_valid_queue_name("a.b"));
        assert!(!is_valid_queue_name("é"));
    }

    #[test]
    fn integers_must_be_plain() {
        let code = |line: &str| parse(line.as_bytes()).unwrap_err().code;
        assert!(parse(br#"{"Command":"Tick","Seconds":30}"#).is_ok());
        for bad in ["30.0", "3e1", "\"30\"", "-1", "1209601"] {
            let line = format!(r#"{{"Command":"Tick","Seconds":{bad}}}"#);
            assert_eq!(code(&line), InvalidParameterValue, "{bad}");
        }
        assert_eq!(code(r#"{"Command":"Tick","Seconds":null}"#), MissingParameter);
    }
}
EOF
