//! Queue state: attributes, messages in arrival order, and deduplication records.

use crate::command::AttrPatch;
use crate::error::{Error, ErrorCode::InvalidParameterValue, Result};
use std::collections::{BTreeMap, HashMap};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeadLetter {
    pub queue: String,
    pub max_receive_count: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Config {
    pub visibility_timeout: u32,
    pub delay_seconds: u32,
    pub retention_seconds: u32,
    pub fifo: bool,
    pub content_based_deduplication: bool,
    pub dead_letter: Option<DeadLetter>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            visibility_timeout: 30,
            delay_seconds: 0,
            retention_seconds: 345_600,
            fifo: false,
            content_based_deduplication: false,
            dead_letter: None,
        }
    }
}

impl Config {
    /// The configuration a `CreateQueue` request asks for: defaults overlaid with the patch.
    pub fn from_patch(patch: &AttrPatch) -> Result<Self> {
        let mut config = Self::default();
        config.apply(patch)?;
        Ok(config)
    }

    /// Overlays the attributes present in `patch`. A dead-letter configuration is
    /// replaced only when the patch names both of its halves.
    pub fn apply(&mut self, patch: &AttrPatch) -> Result<()> {
        let dead_letter = match (&patch.dead_letter_queue, patch.max_receive_count) {
            (Some(queue), Some(max_receive_count)) => {
                Some(DeadLetter { queue: queue.clone(), max_receive_count })
            }
            (None, None) => None,
            _ => {
                return Err(Error::new(
                    InvalidParameterValue,
                    "DeadLetterQueue and MaxReceiveCount must be given together",
                ));
            }
        };
        self.visibility_timeout = patch.visibility_timeout.unwrap_or(self.visibility_timeout);
        self.delay_seconds = patch.delay_seconds.unwrap_or(self.delay_seconds);
        self.retention_seconds = patch.retention_seconds.unwrap_or(self.retention_seconds);
        self.fifo = patch.fifo.unwrap_or(self.fifo);
        self.content_based_deduplication =
            patch.content_based_deduplication.unwrap_or(self.content_based_deduplication);
        if dead_letter.is_some() {
            self.dead_letter = dead_letter;
        }
        Ok(())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum State {
    Visible,
    InFlight,
    Delayed,
}

#[derive(Debug)]
pub struct Message {
    pub id: u64,
    pub body: String,
    pub sent_at: u64,
    pub receive_count: u32,
    pub first_received_at: Option<u64>,
    pub group_id: Option<String>,
    pub sequence_number: Option<u64>,
    /// The message is hidden (delayed or in flight) while `now < hidden_until`.
    pub hidden_until: u64,
    /// The latest receipt handle number issued for this message.
    pub handle: Option<u64>,
}

impl Message {
    pub fn state(&self, now: u64) -> State {
        if now >= self.hidden_until {
            State::Visible
        } else if self.receive_count == 0 {
            State::Delayed
        } else {
            State::InFlight
        }
    }
}

/// The deduplication record of a FIFO queue: the message accepted for an id.
#[derive(Debug, Clone, Copy)]
pub struct Accepted {
    pub at: u64,
    pub message_id: u64,
    pub sequence_number: u64,
}

#[derive(Debug)]
pub struct Queue {
    pub config: Config,
    /// Messages keyed by arrival number, so iteration is arrival order.
    pub messages: BTreeMap<u64, Message>,
    next_arrival: u64,
    next_sequence: u64,
    pub dedup: HashMap<String, Accepted>,
    /// Receipt handle number to the arrival key of the message it was issued for.
    /// Entries of messages that have left the queue are stale and must be checked.
    pub handles: HashMap<u64, u64>,
}

impl Queue {
    pub fn new(config: Config) -> Self {
        Self {
            config,
            messages: BTreeMap::new(),
            next_arrival: 0,
            next_sequence: 1,
            dedup: HashMap::new(),
            handles: HashMap::new(),
        }
    }

    /// Takes the next sequence number of a FIFO queue.
    pub fn take_sequence(&mut self) -> u64 {
        let n = self.next_sequence;
        self.next_sequence += 1;
        n
    }

    /// Adds `message` at the end of the queue.
    pub fn push(&mut self, message: Message) {
        self.messages.insert(self.next_arrival, message);
        self.next_arrival += 1;
    }

    /// Removes every message that retention has expired at `now`.
    pub fn expire(&mut self, now: u64) {
        let retention = u64::from(self.config.retention_seconds);
        self.messages.retain(|_, m| now < m.sent_at + retention);
    }

    pub fn purge(&mut self) {
        self.messages.clear();
        self.handles.clear();
    }

    /// Arrival key of the message that `handle` is the latest handle of, if it is in flight.
    pub fn in_flight_key(&self, handle: u64, now: u64) -> Option<u64> {
        let key = *self.handles.get(&handle)?;
        let message = self.messages.get(&key)?;
        (message.state(now) == State::InFlight).then_some(key)
    }

    /// Counts of visible, in-flight and delayed messages.
    pub fn counts(&self, now: u64) -> [usize; 3] {
        let mut counts = [0; 3];
        for message in self.messages.values() {
            counts[message.state(now) as usize] += 1;
        }
        counts
    }
}
