//! The miniq state machine: executes one [`Command`] at a time against in-memory queues.

use crate::command::{self, AttrPatch, Command, Send};
use crate::error::{Error, ErrorCode::*, Result};
use crate::queue::{Accepted, Config, DeadLetter, Message, Queue};
use serde_json::{Value, json};
use std::collections::{BTreeMap, HashSet};

const MAX_QUEUES: usize = 1000;
const MAX_MESSAGES: usize = 100_000;
const DEDUP_WINDOW: u64 = 300;

#[derive(Debug)]
pub struct Service {
    now: u64,
    messages_accepted: u64,
    deliveries: u64,
    queues: BTreeMap<String, Queue>,
}

fn no_queue(name: &str) -> Error {
    Error::new(QueueDoesNotExist, format!("queue {name:?} does not exist"))
}

impl Default for Service {
    fn default() -> Self {
        Self::new()
    }
}

impl Service {
    pub fn new() -> Self {
        Self { now: 0, messages_accepted: 0, deliveries: 0, queues: BTreeMap::new() }
    }

    /// Runs one input line and returns its response object.
    pub fn handle_line(&mut self, line: &[u8]) -> Value {
        match command::parse(line).and_then(|command| self.execute(command)) {
            Ok(Value::Object(mut result)) => {
                result.insert("ok".into(), Value::Bool(true));
                Value::Object(result)
            }
            Ok(other) => unreachable!("results are objects, got {other}"),
            Err(error) => error.to_response(),
        }
    }

    fn execute(&mut self, command: Command) -> Result<Value> {
        // Rule 4 of SPEC section 2 (queue lookup) precedes every command's own rules.
        let queue_of = |command: &Command| match command {
            Command::SetQueueAttributes { queue, .. }
            | Command::GetQueueAttributes { queue }
            | Command::DeleteQueue { queue }
            | Command::PurgeQueue { queue }
            | Command::ReceiveMessage { queue, .. }
            | Command::DeleteMessage { queue, .. }
            | Command::ChangeMessageVisibility { queue, .. }
            | Command::SendMessage(Send { queue, .. }) => Some(queue.clone()),
            _ => None,
        };
        if let Some(name) = queue_of(&command)
            && !self.queues.contains_key(&name)
        {
            return Err(no_queue(&name));
        }
        match command {
            Command::CreateQueue { name, attributes } => self.create_queue(name, &attributes),
            Command::SetQueueAttributes { queue, attributes } => self.set_attributes(&queue, &attributes),
            Command::GetQueueAttributes { queue } => Ok(self.get_attributes(&queue)),
            Command::ListQueues { prefix } => Ok(self.list_queues(prefix.as_deref().unwrap_or(""))),
            Command::DeleteQueue { queue } => Ok(self.delete_queue(&queue)),
            Command::PurgeQueue { queue } => {
                self.queues.get_mut(&queue).map(Queue::purge);
                Ok(json!({}))
            }
            Command::Tick { seconds } => Ok(self.tick(seconds)),
            Command::SendMessage(send) => self.send(send),
            Command::ReceiveMessage { queue, max_messages, visibility_timeout } => {
                Ok(self.receive(&queue, max_messages, visibility_timeout))
            }
            Command::DeleteMessage { queue, receipt_handle } => self.delete_message(&queue, &receipt_handle),
            Command::ChangeMessageVisibility { queue, receipt_handle, visibility_timeout } => {
                self.change_visibility(&queue, &receipt_handle, visibility_timeout)
            }
        }
    }

    fn create_queue(&mut self, name: String, attributes: &AttrPatch) -> Result<Value> {
        let config = Config::from_patch(attributes)?;
        if name.ends_with(".fifo") != config.fifo {
            return Err(Error::new(QueueNameInvalid, "a queue name ends in .fifo exactly when Fifo is true"));
        }
        if config.content_based_deduplication && !config.fifo {
            return Err(Error::new(InvalidParameterValue, "ContentBasedDeduplication requires Fifo"));
        }
        if let Some(existing) = self.queues.get(&name) {
            return if existing.config == config {
                Ok(json!({}))
            } else {
                Err(Error::new(QueueAlreadyExists, format!("queue {name:?} exists with other attributes")))
            };
        }
        if let Some(DeadLetter { queue, .. }) = &config.dead_letter {
            let target = self.queues.get(queue).ok_or_else(|| no_queue(queue))?;
            if target.config.fifo != config.fifo {
                return Err(Error::new(InvalidParameterValue, "dead-letter queue has a different Fifo"));
            }
        }
        if self.queues.len() >= MAX_QUEUES {
            return Err(Error::new(LimitExceeded, "1000 queues exist"));
        }
        self.queues.insert(name, Queue::new(config));
        Ok(json!({}))
    }

    fn set_attributes(&mut self, name: &str, patch: &AttrPatch) -> Result<Value> {
        let current = &self.queues[name].config;
        if patch.fifo.is_some() {
            return Err(Error::new(UnsupportedOperation, "the type of a queue cannot change"));
        }
        if patch.content_based_deduplication == Some(true) && !current.fifo {
            return Err(Error::new(InvalidParameterValue, "ContentBasedDeduplication requires a FIFO queue"));
        }
        let mut config = current.clone();
        config.apply(patch)?;
        if let Some(dead_letter) = patch.dead_letter_queue.as_deref() {
            let target = self.queues.get(dead_letter).ok_or_else(|| no_queue(dead_letter))?;
            if dead_letter == name || target.config.fifo != config.fifo {
                return Err(Error::new(
                    InvalidParameterValue,
                    "dead-letter queue must be another queue of the same type",
                ));
            }
        }
        let now = self.now;
        let queue = self.queues.get_mut(name).ok_or_else(|| no_queue(name))?;
        queue.config = config;
        queue.expire(now);
        Ok(json!({}))
    }

    fn get_attributes(&self, name: &str) -> Value {
        let queue = &self.queues[name];
        let config = &queue.config;
        let mut attributes = json!({
            "VisibilityTimeout": config.visibility_timeout,
            "DelaySeconds": config.delay_seconds,
            "RetentionSeconds": config.retention_seconds,
            "Fifo": config.fifo,
            "ContentBasedDeduplication": config.content_based_deduplication,
        });
        if let Some(dead_letter) = &config.dead_letter {
            attributes["DeadLetterQueue"] = json!(dead_letter.queue);
            attributes["MaxReceiveCount"] = json!(dead_letter.max_receive_count);
        }
        let [visible, in_flight, delayed] = queue.counts(self.now);
        json!({
            "Attributes": attributes,
            "Counts": {"Visible": visible, "InFlight": in_flight, "Delayed": delayed},
        })
    }

    fn list_queues(&self, prefix: &str) -> Value {
        let names: Vec<_> = self
            .queues
            .range::<str, _>(prefix..)
            .map(|(name, _)| name)
            .take_while(|name| name.starts_with(prefix))
            .collect();
        json!({"QueueNames": names})
    }

    fn delete_queue(&mut self, name: &str) -> Value {
        self.queues.remove(name);
        for queue in self.queues.values_mut() {
            if queue.config.dead_letter.as_ref().is_some_and(|d| d.queue == name) {
                queue.config.dead_letter = None;
            }
        }
        json!({})
    }

    fn tick(&mut self, seconds: u32) -> Value {
        self.now += u64::from(seconds);
        for queue in self.queues.values_mut() {
            queue.expire(self.now);
        }
        json!({"Now": self.now})
    }

    fn send(&mut self, send: Send) -> Result<Value> {
        let now = self.now;
        let queue = self.queues.get_mut(&send.queue).ok_or_else(|| no_queue(&send.queue))?;
        let fifo = queue.config.fifo;
        if fifo && send.delay_seconds.is_some() || !fifo && (send.group_id.is_some() || send.deduplication_id.is_some()) {
            return Err(Error::new(UnsupportedOperation, "parameter not supported by this type of queue"));
        }
        let mut dedup_id = None;
        if fifo {
            if send.group_id.is_none() {
                return Err(Error::new(MissingParameter, "GroupId is required"));
            }
            let id = match &send.deduplication_id {
                Some(id) => id.clone(),
                None if queue.config.content_based_deduplication => send.body.clone(),
                None => return Err(Error::new(MissingParameter, "DeduplicationId is required")),
            };
            if let Some(original) = queue.dedup.get(&id).filter(|a| now - a.at < DEDUP_WINDOW) {
                return Ok(json!({"MessageId": format!("m-{}", original.message_id), "SequenceNumber": original.sequence_number}));
            }
            dedup_id = Some(id);
        }
        if queue.messages.len() >= MAX_MESSAGES {
            return Err(Error::new(LimitExceeded, "queue holds 100000 messages"));
        }
        self.messages_accepted += 1;
        let id = self.messages_accepted;
        let delay = send.delay_seconds.unwrap_or(queue.config.delay_seconds);
        let sequence_number = fifo.then(|| queue.take_sequence());
        queue.push(Message {
            id,
            body: send.body,
            sent_at: now,
            receive_count: 0,
            first_received_at: None,
            group_id: send.group_id,
            sequence_number,
            hidden_until: now + u64::from(delay),
            handle: None,
        });
        let mut result = json!({"MessageId": format!("m-{id}")});
        if let (Some(dedup_id), Some(sequence_number)) = (dedup_id, sequence_number) {
            queue.dedup.insert(dedup_id, Accepted { at: now, message_id: id, sequence_number });
            result["SequenceNumber"] = json!(sequence_number);
        }
        Ok(result)
    }

    fn receive(&mut self, name: &str, max_messages: u32, visibility: Option<u32>) -> Value {
        let now = self.now;
        let Some(queue) = self.queues.get_mut(name) else { return json!({"Messages": []}) };
        let visibility = u64::from(visibility.unwrap_or(queue.config.visibility_timeout));
        let dead_letter = queue.config.dead_letter.clone();
        let fifo = queue.config.fifo;
        let mut delivered = Vec::new();
        let mut moved = Vec::new();
        // Groups with an earlier message still in the queue (FIFO only).
        let mut blocked: HashSet<String> = HashSet::new();
        for (&key, message) in queue.messages.iter_mut() {
            if delivered.len() >= max_messages as usize {
                break;
            }
            if let Some(group) = &message.group_id {
                if blocked.contains(group) {
                    continue;
                }
                if message.state(now) != crate::queue::State::Visible {
                    blocked.insert(group.clone());
                    continue;
                }
            } else if message.state(now) != crate::queue::State::Visible {
                continue;
            }
            if let Some(dead_letter) = &dead_letter
                && message.receive_count >= dead_letter.max_receive_count
            {
                moved.push(key);
                continue;
            }
            self.deliveries += 1;
            let handle = self.deliveries;
            if let Some(old) = message.handle.replace(handle) {
                queue.handles.remove(&old);
            }
            queue.handles.insert(handle, key);
            message.receive_count += 1;
            message.first_received_at.get_or_insert(now);
            message.hidden_until = now + visibility;
            if let Some(group) = &message.group_id {
                blocked.insert(group.clone());
            }
            let mut out = json!({
                "MessageId": format!("m-{}", message.id),
                "ReceiptHandle": format!("r-{handle}"),
                "Body": message.body,
                "ReceiveCount": message.receive_count,
                "SentAt": message.sent_at,
                "FirstReceivedAt": message.first_received_at,
            });
            if fifo {
                out["GroupId"] = json!(message.group_id);
                out["SequenceNumber"] = json!(message.sequence_number);
            }
            delivered.push(out);
        }
        let moved: Vec<Message> = moved.into_iter().filter_map(|key| queue.messages.remove(&key)).collect();
        if let Some(dead_letter) = dead_letter {
            self.move_to_dead_letter(&dead_letter.queue, moved);
        }
        json!({"Messages": delivered})
    }

    /// Appends `messages` to the dead-letter queue as fresh, immediately visible messages.
    fn move_to_dead_letter(&mut self, name: &str, messages: Vec<Message>) {
        let now = self.now;
        let Some(queue) = self.queues.get_mut(name) else { return };
        let retention = u64::from(queue.config.retention_seconds);
        for mut message in messages {
            message.receive_count = 0;
            message.first_received_at = None;
            message.hidden_until = 0;
            message.handle = None;
            message.sequence_number = queue.config.fifo.then(|| queue.take_sequence());
            if now < message.sent_at + retention {
                queue.push(message);
            }
        }
    }

    /// Parses `r-<n>` and checks that handle `n` has been issued; the text must be canonical.
    fn issued_handle(&self, handle: &str) -> Result<u64> {
        handle
            .strip_prefix("r-")
            .filter(|n| !n.starts_with('0') && n.bytes().all(|b| b.is_ascii_digit()))
            .and_then(|n| n.parse::<u64>().ok())
            .filter(|&n| n <= self.deliveries)
            .ok_or_else(|| Error::new(ReceiptHandleInvalid, format!("receipt handle {handle:?} was never issued")))
    }

    /// Arrival key of the in-flight message `handle` belongs to in queue `name`.
    fn locate(&self, name: &str, handle: &str) -> Result<u64> {
        let number = self.issued_handle(handle)?;
        self.queues[name]
            .in_flight_key(number, self.now)
            .ok_or_else(|| Error::new(ReceiptHandleExpired, format!("receipt handle {handle:?} is no longer usable")))
    }

    fn delete_message(&mut self, name: &str, handle: &str) -> Result<Value> {
        let key = self.locate(name, handle)?;
        let queue = self.queues.get_mut(name).ok_or_else(|| no_queue(name))?;
        queue.messages.remove(&key);
        Ok(json!({}))
    }

    fn change_visibility(&mut self, name: &str, handle: &str, visibility: u32) -> Result<Value> {
        let key = self.locate(name, handle)?;
        let now = self.now;
        let queue = self.queues.get_mut(name).ok_or_else(|| no_queue(name))?;
        if let Some(message) = queue.messages.get_mut(&key) {
            message.hidden_until = now + u64::from(visibility);
        }
        Ok(json!({}))
    }
}
