use std::io::Write;
use std::process::{Command, Stdio};

fn run(input: &str) -> Vec<Value> {
    let mut child = Command::new(env!("CARGO_BIN_EXE_miniq"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    child.stdin.take().unwrap().write_all(input.as_bytes()).unwrap();
    let out = child.wait_with_output().unwrap();
    assert!(out.status.success());
    String::from_utf8(out.stdout).unwrap().lines().map(|l| serde_json::from_str(l).unwrap()).collect()
}

fn code(response: &Value) -> &str {
    assert_eq!(response["ok"], false, "{response}");
    response["error"]["code"].as_str().unwrap()
}

#[test]
fn every_line_gets_one_response_including_unterminated_last() {
    let out = run("\n{\"Command\":\"Tick\",\"Seconds\":5}\nnot json\n{\"Command\":\"Tick\",\"Seconds\":1}");
    assert_eq!(out.len(), 4);
    assert_eq!(code(&out[0]), "InvalidRequest");
    assert_eq!(out[1], json!({"ok": true, "Now": 5}));
    assert_eq!(code(&out[2]), "InvalidRequest");
    assert_eq!(out[3], json!({"ok": true, "Now": 6}));
}

#[test]
fn visibility_timeout_and_handles() {
    let out = run(concat!(
        "{\"Command\":\"CreateQueue\",\"QueueName\":\"q\"}\n",
        "{\"Command\":\"SendMessage\",\"QueueName\":\"q\",\"Body\":\"hi\"}\n",
        "{\"Command\":\"ReceiveMessage\",\"QueueName\":\"q\"}\n",
        "{\"Command\":\"ReceiveMessage\",\"QueueName\":\"q\"}\n",
        "{\"Command\":\"Tick\",\"Seconds\":30}\n",
        "{\"Command\":\"DeleteMessage\",\"QueueName\":\"q\",\"ReceiptHandle\":\"r-1\"}\n",
        "{\"Command\":\"DeleteMessage\",\"QueueName\":\"q\",\"ReceiptHandle\":\"r-01\"}\n",
        "{\"Command\":\"ReceiveMessage\",\"QueueName\":\"q\"}\n",
        "{\"Command\":\"DeleteMessage\",\"QueueName\":\"q\",\"ReceiptHandle\":\"r-2\"}\n",
    ));
    assert_eq!(out[1], json!({"ok": true, "MessageId": "m-1"}));
    assert_eq!(
        out[2],
        json!({"ok": true, "Messages": [{"MessageId": "m-1", "ReceiptHandle": "r-1", "Body": "hi",
            "ReceiveCount": 1, "SentAt": 0, "FirstReceivedAt": 0}]})
    );
    assert_eq!(out[3], json!({"ok": true, "Messages": []}));
    assert_eq!(code(&out[5]), "ReceiptHandleExpired");
    assert_eq!(code(&out[6]), "ReceiptHandleInvalid");
    assert_eq!(out[7]["Messages"][0]["ReceiveCount"], 2);
    assert_eq!(out[8], json!({"ok": true}));
}

#[test]
fn fifo_groups_dedup_and_dead_letters() {
    let out = run(concat!(
        "{\"Command\":\"CreateQueue\",\"QueueName\":\"dlq.fifo\",\"Attributes\":{\"Fifo\":true}}\n",
        "{\"Command\":\"CreateQueue\",\"QueueName\":\"q.fifo\",\"Attributes\":{\"Fifo\":true,\"VisibilityTimeout\":0,\"DeadLetterQueue\":\"dlq.fifo\",\"MaxReceiveCount\":1}}\n",
        "{\"Command\":\"SendMessage\",\"QueueName\":\"q.fifo\",\"Body\":\"a\",\"GroupId\":\"g\",\"DeduplicationId\":\"d\"}\n",
        "{\"Command\":\"SendMessage\",\"QueueName\":\"q.fifo\",\"Body\":\"b\",\"GroupId\":\"g\",\"DeduplicationId\":\"d\"}\n",
        "{\"Command\":\"SendMessage\",\"QueueName\":\"q.fifo\",\"Body\":\"c\",\"GroupId\":\"g\",\"DeduplicationId\":\"e\"}\n",
        "{\"Command\":\"ReceiveMessage\",\"QueueName\":\"q.fifo\",\"MaxMessages\":10}\n",
        "{\"Command\":\"ReceiveMessage\",\"QueueName\":\"q.fifo\",\"MaxMessages\":10}\n",
        "{\"Command\":\"GetQueueAttributes\",\"QueueName\":\"dlq.fifo\"}\n",
    ));
    assert_eq!(out[2], json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(out[3], out[2]);
    assert_eq!(out[4]["MessageId"], "m-2");
    assert_eq!(out[5]["Messages"].as_array().unwrap().len(), 1);
    // `a` has now reached MaxReceiveCount: it moves, and `c` is delivered in the same pass.
    assert_eq!(out[6]["Messages"][0]["Body"], "c");
    assert_eq!(out[7]["Counts"], json!({"Visible": 1, "InFlight": 0, "Delayed": 0}));
}

#[test]
fn queue_rules_and_listing() {
    let out = run(concat!(
        "{\"Command\":\"CreateQueue\",\"QueueName\":\"b\"}\n",
        "{\"Command\":\"CreateQueue\",\"QueueName\":\"B\"}\n",
        "{\"Command\":\"CreateQueue\",\"QueueName\":\"b\",\"Attributes\":{\"DelaySeconds\":1}}\n",
        "{\"Command\":\"CreateQueue\",\"QueueName\":\"x.fifo\"}\n",
        "{\"Command\":\"CreateQueue\"}\n",
        "{\"Command\":\"ListQueues\",\"Prefix\":\"\"}\n",
        "{\"Command\":\"SetQueueAttributes\",\"QueueName\":\"nope\",\"Attributes\":{\"Bogus\":1}}\n",
        "{\"Command\":\"SetQueueAttributes\",\"QueueName\":\"b\",\"Attributes\":{\"Fifo\":false}}\n",
    ));
    assert_eq!(code(&out[2]), "QueueAlreadyExists");
    assert_eq!(code(&out[3]), "QueueNameInvalid");
    assert_eq!(code(&out[4]), "MissingParameter");
    assert_eq!(out[5]["QueueNames"], json!(["B", "b"]));
    assert_eq!(code(&out[6]), "InvalidParameterValue");
    assert_eq!(code(&out[7]), "UnsupportedOperation");
}

#[test]
fn retention_removes_messages_and_filling_a_queue_is_fast() {
    let mut input = String::from("{\"Command\":\"CreateQueue\",\"QueueName\":\"q\"}\n");
    for _ in 0..100_000 {
        input.push_str("{\"Command\":\"SendMessage\",\"QueueName\":\"q\",\"Body\":\"x\"}\n");
    }
    input.push_str("{\"Command\":\"SendMessage\",\"QueueName\":\"q\",\"Body\":\"x\"}\n");
    input.push_str("{\"Command\":\"Tick\",\"Seconds\":345600}\n{\"Command\":\"GetQueueAttributes\",\"QueueName\":\"q\"}\n");
    let out = run(&input);
    assert_eq!(code(&out[100_001]), "LimitExceeded");
    assert_eq!(out[100_003]["Counts"], json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}
EOF
cargo test 2>&1 | grep -E "^(error|warning)|test |panicked|left|right" -A4 | head -50

